"use client";

// segment-404 · 404lab
// Requires ./chrome.tsx and the 404lab tokens.

import { motion, useReducedMotion } from "motion/react";
import { Caption, Foot, Screen, useReplay } from "./chrome";

const DIGITS = ["4", "0", "4"];

/* --------------------------------- segment --------------------------------- */

const SEGMENTS = {
  a: "8,3 32,3 29,7 11,7",
  b: "33,4 37,8 37,30 33,27",
  c: "33,36 37,39 37,61 33,57",
  d: "8,60 32,60 29,56 11,56",
  e: "3,36 7,39 7,61 3,57",
  f: "3,4 7,8 7,30 3,27",
  g: "8,31 32,31 29,34 11,34",
} as const;

const SEVEN: Record<string, (keyof typeof SEGMENTS)[]> = {
  "4": ["b", "c", "f", "g"],
  "0": ["a", "b", "c", "d", "e", "f"],
  "8": ["a", "b", "c", "d", "e", "f", "g"],
};

function SevenSegment({
  digit,
  run,
  reduce,
  index,
}: {
  digit: string;
  run: number;
  reduce: boolean;
  index: number;
}) {
  const lit = SEVEN[digit];
  return (
    <div className="relative grid h-[96px] w-[66px] place-items-center rounded-[4px] border border-line-2 bg-ink-850/70 shadow-[inset_0_1px_0_rgba(255,255,255,0.04)]">
      <svg viewBox="0 0 40 64" className="h-[76px] w-[48px]" aria-hidden>
        {(Object.keys(SEGMENTS) as (keyof typeof SEGMENTS)[]).map((key, i) => {
          const on = lit.includes(key);
          return (
            <motion.polygon
              key={`${run}-${key}`}
              points={SEGMENTS[key]}
              fill="#f2ede3"
              initial={reduce ? false : { opacity: 0 }}
              whileInView={{ opacity: on ? 0.94 : 0.07 }}
              viewport={{ once: true }}
              transition={{
                duration: 0.22,
                delay: reduce ? 0 : index * 0.16 + i * 0.035,
              }}
            />
          );
        })}
      </svg>
      <span className="absolute right-1.5 top-1.5 size-1 rounded-full bg-amber/25" />
    </div>
  );
}

export function SegmentDemo() {
  const reduce = useReducedMotion();
  const { run, replay } = useReplay();

  return (
    <Screen onPointerEnter={replay} onClick={replay} className="bg-[#07080a]">
      <div className="absolute inset-0 bg-[linear-gradient(90deg,rgba(242,237,227,0.035)_0_1px,transparent_1px_23px)]" />

      <div className="absolute inset-0 z-10 flex flex-col items-center justify-center gap-4">
        <div className="flex items-center gap-2">
          {DIGITS.map((d, i) => (
            <SevenSegment
              key={`${run}-${i}`}
              digit={d}
              run={run}
              reduce={reduce ?? false}
              index={i}
            />
          ))}
        </div>
        <div className="flex w-[214px] items-center justify-between lab-mono text-[8.5px] text-white/40">
          <span>DIGIT MODULE</span>
          <span className="text-amber/70">404</span>
        </div>
      </div>

      <div className="pointer-events-none absolute bottom-9 left-4 lab-mono text-[9.5px] text-white/35">
        7 bars · 3 cells
      </div>

      <Caption label="404 / segment" />
      <Foot method="7 segments · 3 cells" />
    </Screen>
  );
}

"use client";

import Image from "next/image";
import { motion, useReducedMotion } from "motion/react";
import { useState } from "react";
import { ArrowUpRight, Check, Copy } from "lucide-react";

export const EASE = [0.22, 1, 0.36, 1] as const;

/* Every card shares the same framing so the grid reads as one set. */

export function Caption({
  label,
  className = "",
}: {
  label: string;
  className?: string;
}) {
  return (
    <span
      className={`pointer-events-none absolute left-4 top-3 z-20 lab-mono text-[10px] tracking-[0.02em] text-white/75 [text-shadow:0_1px_3px_rgba(8,9,10,0.6)] ${className}`}
    >
      {label}
    </span>
  );
}

export function HomeLink({ label = "back home" }: { label?: string }) {
  return (
    <span className="pointer-events-none inline-flex items-center gap-1 lab-mono text-[10px] text-white/70">
      {label}
      <ArrowUpRight className="size-3" strokeWidth={1.5} />
    </span>
  );
}

export function Foot({
  method,
  label,
}: {
  method: string;
  label?: string;
}) {
  return (
    <div className="pointer-events-none absolute inset-x-0 bottom-0 z-20 flex items-center justify-between px-4 pb-3">
      <HomeLink label={label} />
      <span className="lab-mono text-[10px] text-white/50">{method}</span>
    </div>
  );
}

const SCREEN =
  "group @container relative h-full w-full overflow-hidden bg-ink-900";

export function Screen({
  className = "",
  children,
  ...rest
}: React.ComponentProps<"div">) {
  return (
    <div {...rest} className={`${SCREEN} ${className}`}>
      {children}
    </div>
  );
}

export function ScreenButton({
  className = "",
  children,
  ...rest
}: React.ComponentProps<"button">) {
  return (
    <button
      type="button"
      {...rest}
      className={`${SCREEN} cursor-default text-left ${className}`}
    >
      {children}
    </button>
  );
}

export function Plate({
  src,
  className = "",
  sizes = "(max-width: 768px) 100vw, 33vw",
  opacity,
  position = "center",
}: {
  src: string;
  className?: string;
  sizes?: string;
  opacity?: number;
  position?: string;
}) {
  return (
    <Image
      src={src}
      alt=""
      fill
      sizes={sizes}
      className={`object-cover ${className}`}
      style={{ opacity, objectPosition: position }}
    />
  );
}

/* --------------------------------- helpers -------------------------------- */

export function useReplay() {
  const [run, setRun] = useState(0);
  return { run, replay: () => setRun((n) => n + 1) };
}

export function useStill() {
  return useReducedMotion() ?? false;
}

export const clamp = (v: number, min: number, max: number) =>
  Math.max(min, Math.min(max, v));

/* ------------------------------- install bits ------------------------------ */

export function CopyCommand({
  command,
  className = "",
}: {
  command: string;
  className?: string;
}) {
  const [done, setDone] = useState(false);

  async function copy() {
    try {
      await navigator.clipboard.writeText(command);
      setDone(true);
      setTimeout(() => setDone(false), 1600);
    } catch {
      setDone(false);
    }
  }

  return (
    <button
      type="button"
      onClick={copy}
      aria-label={`Copy ${command}`}
      className={`group/copy flex w-full items-center justify-between gap-4 rounded-control border border-line bg-ink-900 px-3 py-2.5 text-left transition-colors duration-200 hover:border-line-2 active:translate-y-px ${className}`}
    >
      <code className="min-w-0 break-all lab-mono text-[10px] text-fg-2 sm:truncate lg:text-[12px]">
        <span className="mr-1.5 text-amber/80">$</span>
        {command}
      </code>
      <span className="shrink-0 text-fg-3 transition-colors duration-200 group-hover/copy:text-fg">
        {done ? (
          <Check className="size-4" strokeWidth={1.5} />
        ) : (
          <Copy className="size-4" strokeWidth={1.5} />
        )}
      </span>
    </button>
  );
}

export function Reveal({
  children,
  delay = 0,
  className = "",
}: {
  children: React.ReactNode;
  delay?: number;
  className?: string;
}) {
  const reduce = useReducedMotion();
  return (
    <motion.div
      className={className}
      initial={reduce ? false : { opacity: 0, y: 10 }}
      whileInView={{ opacity: 1, y: 0 }}
      viewport={{ once: true, margin: "-60px" }}
      transition={{ duration: 0.55, ease: EASE, delay }}
    >
      {children}
    </motion.div>
  );
}
